def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries
            expired_keys = [k for k, (v, wt) in cache.items() if wt + ttl <= t]
            for k in expired_keys:
                del cache[k]

            # If key exists, remove it (will re-add as most recent)
            if key in cache:
                del cache[key]
            # If cache is full and we're adding a new key, evict LRU
            elif len(cache) >= capacity:
                cache.popitem(last=False)  # Remove oldest (least recently used)

            # Add the new entry as most recently used
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries
            expired_keys = [k for k, (v, wt) in cache.items() if wt + ttl <= t]
            for k in expired_keys:
                del cache[k]

            # Get the value
            if key in cache:
                value, write_time = cache[key]
                results.append(value)
                # Make it most recently used
                del cache[key]
                cache[key] = (value, write_time)
            else:
                results.append(-1)

    return results

